coding.solution:
NAMES = ["forward", "loss", "zero_grad", "backward", "step"]
RULES = [("forward", "loss"), ("loss", "backward"), ("zero_grad", "backward"), ("backward", "step")]

def check_step(calls):
    problems = []
    for name in NAMES:
        n = calls.count(name)
        if n == 0:
            problems.append("missing " + name)
        elif n > 1:
            problems.append("duplicate " + name)
    if problems:
        return problems
    for a, b in RULES:
        if calls.index(a) > calls.index(b):
            problems.append(a + " must come before " + b)
    return problems

